import{_ as e,o as a,c as l,ai as r}from"./chunks/framework.CpsiabEW.js";const b=JSON.parse('{"title":"工程化答案","description":"","frontmatter":{},"headers":[],"relativePath":"doc/2.Interview/2.Answer/Answer-2/07-Engineering.md","filePath":"doc/2.Interview/2.Answer/Answer-2/07-Engineering.md"}'),t={name:"doc/2.Interview/2.Answer/Answer-2/07-Engineering.md"};function n(o,i,s,h,c,p){return a(),l("div",null,[...i[0]||(i[0]=[r('<h1 id="工程化答案" tabindex="-1">工程化答案 <a class="header-anchor" href="#工程化答案" aria-label="Permalink to “工程化答案”">​</a></h1><h2 id="一、webpack" tabindex="-1">一、Webpack <a class="header-anchor" href="#一、webpack" aria-label="Permalink to “一、Webpack”">​</a></h2><h3 id="_1-webpack-是什么" tabindex="-1">1. Webpack 是什么？ <a class="header-anchor" href="#_1-webpack-是什么" aria-label="Permalink to “1. Webpack 是什么？”">​</a></h3><p>Webpack是模块打包工具，处理项目中的各种资源。</p><p><strong>核心概念</strong>：</p><ul><li>Entry：入口文件</li><li>Output：输出配置</li><li>Loader：处理非JS文件</li><li>Plugin：扩展功能</li></ul><hr><h3 id="_2-27-webpack配置相关" tabindex="-1">2-27. Webpack配置相关 <a class="header-anchor" href="#_2-27-webpack配置相关" aria-label="Permalink to “2-27. Webpack配置相关”">​</a></h3><p><strong>常用Loader</strong>：</p><ul><li>babel-loader：处理JS/TS</li><li>css-loader/style-loader：处理CSS</li><li>file-loader：处理文件</li></ul><p><strong>常用Plugin</strong>：</p><ul><li>HtmlWebpackPlugin：生成HTML</li><li>MiniCssExtractPlugin：提取CSS</li><li>DefinePlugin：定义环境变量</li></ul><p><strong>优化</strong>：</p><ul><li>Tree Shaking</li><li>Code Splitting</li><li>懒加载</li></ul><hr><h2 id="二、vite" tabindex="-1">二、Vite <a class="header-anchor" href="#二、vite" aria-label="Permalink to “二、Vite”">​</a></h2><h3 id="_23-34-vite相关" tabindex="-1">23-34. Vite相关 <a class="header-anchor" href="#_23-34-vite相关" aria-label="Permalink to “23-34. Vite相关”">​</a></h3><p>Vite是新一代构建工具，基于ESM。</p><p><strong>优势</strong>：</p><ul><li>开发时原生ESM</li><li>生产Rollup打包</li><li>HMR快速</li></ul><hr><h2 id="三、git" tabindex="-1">三、Git <a class="header-anchor" href="#三、git" aria-label="Permalink to “三、Git”">​</a></h2><h3 id="_35-50-git相关" tabindex="-1">35-50. Git相关 <a class="header-anchor" href="#_35-50-git相关" aria-label="Permalink to “35-50. Git相关”">​</a></h3><p><strong>基本命令</strong>：</p><ul><li>git init：初始化</li><li>git clone：克隆</li><li>git add：暂存</li><li>git commit：提交</li><li>git push：推送</li></ul><p><strong>分支操作</strong>：</p><ul><li>git branch：分支</li><li>git checkout：切换</li><li>git merge：合并</li><li>git rebase：变基</li></ul><hr><h2 id="四、babel" tabindex="-1">四、Babel <a class="header-anchor" href="#四、babel" aria-label="Permalink to “四、Babel”">​</a></h2><p><strong>Babel</strong>：</p><ul><li>转译JS代码</li><li>preset-env：最新语法</li><li>polyfill：API填充</li></ul><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>工程化工具提高开发效率和质量。Webpack功能全面，Vite更快速，Git是版本控制基础。</p>',34)])])}const g=e(t,[["render",n]]);export{b as __pageData,g as default};
